package iam

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"reflect"
	"testing"
)

// Regression: an SDK generated by the pre-PR#4 clientgen rendered Smithy map
// shapes (StringMap, StringListMap) as empty structs. AuthzRequest.Context
// then marshalled as {} and every condition key was dropped on the way to
// vex-iam; decoding a role with conditions into the empty struct lost them.

func TestAuthorize_ContextRoundTrips(t *testing.T) {
	want := map[string]string{"vex:SourceTenant": "acme", "vex:Region": "dev-1", "env": "beta"}
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost || r.URL.Path != "/iam/authorize" {
			t.Errorf("got %s %s", r.Method, r.URL.Path)
		}
		raw, _ := io.ReadAll(r.Body)
		var got struct {
			Context map[string]string `json:"context"`
		}
		if err := json.Unmarshal(raw, &got); err != nil {
			t.Fatalf("body %s: %v", raw, err)
		}
		if !reflect.DeepEqual(got.Context, want) {
			t.Errorf("context on the wire = %v (body %s), want %v", got.Context, raw, want)
		}
		_, _ = w.Write([]byte(`{"decision":"allow","reason":"matched"}`))
	}))
	defer srv.Close()

	out, err := New(srv.URL, "tok").Authorize(context.Background(), AuthzRequest{
		Principal: &PrincipalRef{Type: "service", Id: "vex-config"},
		Action:    "vex-config:RegisterService",
		Resource:  "vrn:vex:vex-config:acme:dev-1:instance/a",
		Context:   want,
	})
	if err != nil {
		t.Fatalf("Authorize: %v", err)
	}
	if out.Decision != "allow" {
		t.Fatalf("decision = %q", out.Decision)
	}
}

func TestAuthzRequest_ContextJSONRoundTrip(t *testing.T) {
	in := AuthzRequest{Action: "a", Resource: "r", Context: map[string]string{"k1": "v1", "k2": "v2"}}
	b, err := json.Marshal(in)
	if err != nil {
		t.Fatal(err)
	}
	var back AuthzRequest
	if err := json.Unmarshal(b, &back); err != nil {
		t.Fatal(err)
	}
	if !reflect.DeepEqual(back.Context, in.Context) {
		t.Fatalf("round trip: %s -> %v", b, back.Context)
	}
}

// `vexctl iam role list` decodes ListRoles; conditions are map[string][]string.
func TestListRoles_DecodesConditionMaps(t *testing.T) {
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(`{"roles":[{"slug":"rip-writer","name":"rip-writer",` +
			`"trust_policy":{"principals":[{"type":"service","id":"admin"}],"conditions":{"vex:SourceTenant":["acme","beta"]}},` +
			`"statements":[{"effect":"allow","actions":["vex-config:RegisterService"],"resources":["*"],"conditions":{"vex:Region":["dev-1"]}}]}]}`))
	}))
	defer srv.Close()

	out, err := New(srv.URL, "tok").ListRoles(context.Background())
	if err != nil {
		t.Fatalf("ListRoles: %v", err)
	}
	if len(out.Roles) != 1 {
		t.Fatalf("roles = %d", len(out.Roles))
	}
	r := out.Roles[0]
	if got := r.TrustPolicy.Conditions["vex:SourceTenant"]; !reflect.DeepEqual(got, []string{"acme", "beta"}) {
		t.Fatalf("trust conditions = %v", r.TrustPolicy.Conditions)
	}
	if got := r.Statements[0].Conditions["vex:Region"]; !reflect.DeepEqual(got, []string{"dev-1"}) {
		t.Fatalf("statement conditions = %v", r.Statements[0].Conditions)
	}
}
